/**
 * What a database from before image sizes were removed still holds: the
 * media table's `sizes` column and the `image_sizes` table.
 *
 * Neither is in Nextly's definitions any more, so a test that needs a database
 * in that state builds it from the definitions as they last stood, frozen
 * here: the state an upgrade meets does not change when the current schema
 * does. The table's DDL is generated by drizzle-kit from that definition, as
 * a fresh install generated it then, rather than written by hand.
 */
import type { SupportedDialect } from "@nextlyhq/adapter-drizzle/types";
import { sql, type SQL } from "drizzle-orm";
import {
  boolean as mysqlBoolean,
  datetime,
  int,
  mysqlTable,
  uniqueIndex as mysqlUniqueIndex,
  varchar as mysqlVarchar,
} from "drizzle-orm/mysql-core";
import {
  boolean as pgBoolean,
  integer as pgInteger,
  pgTable,
  text as pgText,
  timestamp,
  uniqueIndex as pgUniqueIndex,
  varchar as pgVarchar,
} from "drizzle-orm/pg-core";
import {
  integer as sqliteInteger,
  sqliteTable,
  text as sqliteText,
  uniqueIndex as sqliteUniqueIndex,
} from "drizzle-orm/sqlite-core";

import { getDrizzleKitForDialect } from "../../database/drizzle-kit-lazy";

/** The `image_sizes` table as each dialect last declared it. */
function retiredImageSizesTable(dialect: SupportedDialect): unknown {
  switch (dialect) {
    case "postgresql":
      return pgTable(
        "image_sizes",
        {
          id: pgText("id").primaryKey(),
          name: pgVarchar("name", { length: 50 }).notNull(),
          width: pgInteger("width"),
          height: pgInteger("height"),
          fit: pgVarchar("fit", { length: 20 }).notNull().default("inside"),
          quality: pgInteger("quality").notNull().default(80),
          format: pgVarchar("format", { length: 10 }).notNull().default("auto"),
          isDefault: pgBoolean("is_default").notNull().default(true),
          sortOrder: pgInteger("sort_order").notNull().default(0),
          createdAt: timestamp("created_at", { withTimezone: false })
            .defaultNow()
            .notNull(),
          updatedAt: timestamp("updated_at", { withTimezone: false })
            .defaultNow()
            .notNull(),
        },
        t => [pgUniqueIndex("image_sizes_name_unique").on(t.name)]
      );
    case "mysql":
      return mysqlTable(
        "image_sizes",
        {
          id: mysqlVarchar("id", { length: 36 }).primaryKey(),
          name: mysqlVarchar("name", { length: 50 }).notNull(),
          width: int("width"),
          height: int("height"),
          fit: mysqlVarchar("fit", { length: 20 }).notNull().default("inside"),
          quality: int("quality").notNull().default(80),
          format: mysqlVarchar("format", { length: 10 })
            .notNull()
            .default("auto"),
          isDefault: mysqlBoolean("is_default").notNull().default(true),
          sortOrder: int("sort_order").notNull().default(0),
          createdAt: datetime("created_at").notNull(),
          updatedAt: datetime("updated_at").notNull(),
        },
        t => [mysqlUniqueIndex("image_sizes_name_unique").on(t.name)]
      );
    case "sqlite":
      return sqliteTable(
        "image_sizes",
        {
          id: sqliteText("id").primaryKey(),
          name: sqliteText("name").notNull(),
          width: sqliteInteger("width"),
          height: sqliteInteger("height"),
          fit: sqliteText("fit").notNull().default("inside"),
          quality: sqliteInteger("quality").notNull().default(80),
          format: sqliteText("format").notNull().default("auto"),
          isDefault: sqliteInteger("is_default", { mode: "boolean" })
            .notNull()
            .default(true),
          sortOrder: sqliteInteger("sort_order").notNull().default(0),
          createdAt: sqliteInteger("created_at", {
            mode: "timestamp",
          }).notNull(),
          updatedAt: sqliteInteger("updated_at", {
            mode: "timestamp",
          }).notNull(),
        },
        t => [sqliteUniqueIndex("image_sizes_name_unique").on(t.name)]
      );
  }
}

/** The statements that create the retired `image_sizes` table on `dialect`. */
export async function retiredImageSizesTableDdl(
  dialect: SupportedDialect
): Promise<string[]> {
  const kit = await getDrizzleKitForDialect(dialect);
  return kit.generateMigration(
    await kit.generateDrizzleJson({}),
    await kit.generateDrizzleJson({
      imageSizes: retiredImageSizesTable(dialect),
    } as never)
  );
}

/** The column's type as each dialect declared it. */
const SIZES_TYPE: Record<SupportedDialect, string> = {
  postgresql: "jsonb",
  mysql: "json",
  sqlite: "text",
};

/** The statement that gives the media table its retired `sizes` column. */
export function retiredSizesColumnDdl(dialect: SupportedDialect): string {
  const q = dialect === "mysql" ? "`" : '"';
  return `ALTER TABLE ${q}media${q} ADD COLUMN ${q}sizes${q} ${SIZES_TYPE[dialect]}`;
}

/** Runs one statement, through whatever raw executor the test holds. */
type Exec = (statement: string) => Promise<unknown> | unknown;

/**
 * Gives a database the retired column and table, as one from before image
 * sizes were removed has them, with one size definition in the table.
 */
export async function addRetiredImageSizes(
  dialect: SupportedDialect,
  exec: Exec
): Promise<void> {
  for (const statement of await retiredImageSizesTableDdl(dialect)) {
    await exec(statement);
  }
  await exec(retiredSizesColumnDdl(dialect));
  const q = dialect === "mysql" ? "`" : '"';
  const at = "'2026-01-01 00:00:00'";
  await exec(
    `INSERT INTO ${q}image_sizes${q} (${q}id${q}, ${q}name${q}, ${q}width${q}, ${q}created_at${q}, ${q}updated_at${q}) VALUES ('size-card', 'card', 400, ${at}, ${at})`
  );
}

/** The SQL that writes an item's retired `sizes`, a JSON text value. */
export function setRetiredSizes(id: string, sizes: string | null): SQL {
  return sql`UPDATE ${sql.identifier("media")} SET ${sql.identifier("sizes")} = ${sizes} WHERE ${sql.identifier("id")} = ${id}`;
}

/** The SQL that reads an item's retired `sizes`. */
export function readRetiredSizes(id: string): SQL {
  return sql`SELECT ${sql.identifier("sizes")} AS ${sql.identifier("sizes")} FROM ${sql.identifier("media")} WHERE ${sql.identifier("id")} = ${id}`;
}

/** Runs a statement that returns no rows on a Drizzle handle of `dialect`. */
export async function runOn(
  db: unknown,
  dialect: SupportedDialect,
  statement: SQL
): Promise<void> {
  if (dialect === "sqlite") (db as { run(q: SQL): unknown }).run(statement);
  else await (db as { execute(q: SQL): Promise<unknown> }).execute(statement);
}

/** An item's retired `sizes`, parsed, or null when it holds none. */
export async function retiredSizesOn(
  db: unknown,
  dialect: SupportedDialect,
  id: string
): Promise<unknown> {
  const statement = readRetiredSizes(id);
  let rows: Array<{ sizes: unknown }>;
  if (dialect === "sqlite") {
    rows = (db as { all(q: SQL): Array<{ sizes: unknown }> }).all(statement);
  } else {
    const raw = await (db as { execute(q: SQL): Promise<unknown> }).execute(
      statement
    );
    rows = (
      Array.isArray(raw)
        ? Array.isArray(raw[0])
          ? raw[0]
          : raw
        : (raw as { rows: unknown[] }).rows
    ) as Array<{ sizes: unknown }>;
  }
  const value = rows[0]?.sizes ?? null;
  return typeof value === "string" ? (JSON.parse(value) as unknown) : value;
}
